<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { showToast, watchToast } from './toast';
import MerchantSelect from './MerchantSelect.vue';
import Catalog from './Catalog.vue';
type Item = { id:number; name:string; status:'active'|'inactive'; description?:string; category?:string|null; merchant_id?:number; merchant_name?:string; category_name?:string|null; category_id?:number|null; price?:string };
const props = defineProps<{ kind:'merchant'|'product'; token:string }>();
const items=ref<Item[]>([]), loading=ref(false), error=ref(''), saving=ref(false), offset=ref(0), hasNext=ref(false), showForm=ref(false), editing=ref<Item|null>(null);
watchToast(error, 'error');
const selectedId=ref<number|null>(null), queryId=ref(''), queried=ref(false);
type ProductCategory = {id:number;name:string;status:string};
const filterMerchant=ref(''), filterCategory=ref(''), filterCategories=ref<ProductCategory[]>([]), formCategories=ref<ProductCategory[]>([]);
const catalogMode=ref<'category'|'sku'|null>(null), catalogMerchant=ref(''), catalogProduct=ref<Item|null>(null);
let filterSequence=0, formSequence=0;
const selected=computed(()=>items.value.find(item=>item.id===selectedId.value));
const categories=ref<{value:string;label:string}[]>([]);
const form=ref({name:'',description:'',category:'',status:'active',merchant_id:'',category_id:'',price:''});
const title=computed(()=>props.kind==='merchant'?'商户':'商品');
const endpoint=computed(()=>props.kind==='merchant'?'/merchants':'/products');
async function api(path:string, method='GET', body?:unknown) {
  let response:Response;
  try { response=await fetch('/api/v1'+path,{method,headers:{Authorization:`Bearer ${props.token}`,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)}); } catch { throw new Error('无法连接服务，请检查后端是否启动。'); }
  if(!response.ok){const data=await response.json().catch(()=>({})); throw new Error(typeof data.detail==='string'?data.detail:'操作失败，请检查输入后重试。');}
  return response.status===204?null:response.json();
}
async function getCategories(merchantId:string):Promise<ProductCategory[]>{const all:ProductCategory[]=[];if(!merchantId)return all;for(let offset=0;;offset+=100){const page:ProductCategory[]=await api(`/categories?merchant_id=${merchantId}&offset=${offset}&limit=100`);all.push(...page);if(page.length<100)return all;}}
async function loadFormCategories(merchantId:string){const seq=++formSequence;formCategories.value=[];try{const data=await getCategories(merchantId);if(seq===formSequence)formCategories.value=data;}catch{if(seq===formSequence)error.value='商品分类加载失败，请重试。';}}
watch(filterMerchant,async value=>{filterCategory.value='';filterCategories.value=[];const seq=++filterSequence;try{const data=await getCategories(value);if(seq===filterSequence)filterCategories.value=data;}catch{if(seq===filterSequence)error.value='商品分类加载失败，请重试。';}});
function formMerchantChange(value:string){form.value.merchant_id=value;form.value.category_id='';void loadFormCategories(value);}
function openCategoryManager(){if(!filterMerchant.value){error.value='请先选择要管理分类的商户。';return;}catalogMerchant.value=filterMerchant.value;catalogMode.value='category';}
async function closeCatalog(){catalogMode.value=null;if(filterMerchant.value){try{filterCategories.value=await getCategories(filterMerchant.value);}catch{error.value='商品分类加载失败，请重试。';}}await load();}
async function load(){loading.value=true;error.value='';selectedId.value=null;try{const params=new URLSearchParams({offset:String(offset.value),limit:'21'});if(props.kind==='product'&&filterMerchant.value)params.set('merchant_id',filterMerchant.value);if(props.kind==='product'&&filterCategory.value)params.set('category_id',filterCategory.value);const data:Item[]=await api(`${endpoint.value}?${params}`);items.value=data.slice(0,20);hasNext.value=data.length>20;queried.value=false;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
watch(()=>props.kind,()=>{if(props.kind==='merchant') void api('/merchant-categories').then(data=>{categories.value=data;}).catch(()=>{error.value='商户类别加载失败，请刷新页面。';});offset.value=0;queryId.value='';showForm.value=false;void load();},{immediate:true});
function open(item?:Item){editing.value=item||null;form.value={name:item?.name||'',description:item?.description||'',category:item?.category||'',status:item?.status||'active',merchant_id:item?.merchant_id?.toString()||'',category_id:item?.category_id?.toString()||'',price:item?.price?.toString()||''};error.value='';if(props.kind==='product')void loadFormCategories(form.value.merchant_id);showForm.value=true;}
async function save(){saving.value=true;error.value='';try{const name=form.value.name.trim();if(!name)throw new Error('请输入名称。');const body:Record<string,unknown>={name,status:form.value.status};if(props.kind==='merchant'){body.description=form.value.description.trim();body.category=form.value.category || null;}else {if(!editing.value)body.merchant_id=Number(form.value.merchant_id);body.category_id=form.value.category_id ? Number(form.value.category_id) : null;body.price=form.value.price;if((!editing.value && (!Number.isInteger(body.merchant_id)||Number(body.merchant_id)<1))||form.value.price===''||!/^\d+(\.\d{1,2})?$/.test(form.value.price))throw new Error('请输入有效的商户编号及最多两位小数的价格。');}await api(endpoint.value+(editing.value?`/${editing.value.id}`:''),editing.value?'PATCH':'POST',body);showForm.value=false;showToast('保存成功');await load();}catch(e){error.value=(e as Error).message;}finally{saving.value=false;}}
async function remove(item:Item){if(!window.confirm(`确定删除${title.value}“${item.name}”吗？此操作无法撤销。`))return;error.value='';try{await api(`${endpoint.value}/${item.id}`,'DELETE');showToast('删除成功');if(items.value.length===1&&offset.value>0)offset.value-=20;await load();}catch(e){error.value=(e as Error).message;}}
async function search(){if(!/^[1-9]\d*$/.test(queryId.value)){error.value='请输入有效的编号。';return;} loading.value=true;error.value='';selectedId.value=null;try{const item:Item=await api(`${endpoint.value}/${queryId.value}`);items.value=props.kind==='product' && ((filterMerchant.value && String(item.merchant_id)!==filterMerchant.value) || (filterCategory.value && String(item.category_id)!==filterCategory.value)) ? [] : [item];queried.value=true;hasNext.value=false;}catch(e){items.value=[];queried.value=true;error.value=(e as Error).message;}finally{loading.value=false;}}
function refresh(){queryId.value='';filterMerchant.value='';filterCategory.value='';offset.value=0;void load();}
function searchFilters(){queryId.value='';offset.value=0;void load();}
function page(delta:number){offset.value+=delta*20;void load();}
</script>
<template><section class="management"><div class="filters"><label>{{ title }}编号 <input v-model.trim="queryId" inputmode="numeric" :aria-label="`${title}编号`" :placeholder="`请输入${title}编号`" @keyup.enter="search"></label><template v-if="kind==='product'"><label>所属商户<MerchantSelect v-model="filterMerchant" class="filter-merchant" :token="token" label="筛选所属商户" /></label><label>商品分类<select v-model="filterCategory" :disabled="!filterMerchant"><option value="">全部分类</option><option v-for="item in filterCategories" :key="item.id" :value="String(item.id)">{{ item.name }}{{ item.status==='inactive'?'（停用）':'' }}</option></select></label></template><div class="filter-actions"><button class="secondary" :disabled="loading" @click="refresh">重置</button><button class="primary-btn" :disabled="loading" @click="kind==='product' && !queryId ? searchFilters() : search()">搜索</button></div></div><div class="panel"><div class="toolbar"><h2>{{ title }}列表</h2><div class="toolbar-actions"><button class="icon-button" @click="refresh" :disabled="loading" title="刷新" aria-label="刷新">↻</button><button v-if="kind==='product'" class="secondary" @click="openCategoryManager">管理分类</button><button class="primary-btn" @click="open()">＋ 新增{{ title }}</button><button class="secondary" :disabled="!selected" @click="selected && remove(selected)">删除</button><button class="secondary" :disabled="!selected" @click="selected && open(selected)">修改</button></div></div><div class="table-wrap"><table :class="kind"><colgroup><col class="col-select"><col class="col-id"><col class="col-name"><col v-if="kind==='merchant'" class="col-category"><col class="col-owner-description"><col v-if="kind==='product'" class="col-product-category"><col v-if="kind==='product'" class="col-price"><col class="col-status"><col class="col-actions"></colgroup><thead><tr><th>选择</th><th>编号</th><th>名称</th><th v-if="kind==='merchant'">商户类别</th><th>{{ kind==='merchant'?'商户描述':'所属商户' }}</th><th v-if="kind==='product'">商品分类</th><th v-if="kind==='product'">价格</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><input v-model="selectedId" type="radio" name="selected-item" :value="item.id" :aria-label="`选择${item.name}`"></td><td><span class="cell-text" :title="String(item.id)">{{ item.id }}</span></td><td class="name"><span class="cell-text" :title="item.name">{{ item.name }}</span></td><td v-if="kind==='merchant'"><span class="cell-text" :title="categories.find(option=>option.value===item.category)?.label || '未分类'">{{ categories.find(option=>option.value===item.category)?.label || '未分类' }}</span></td><td><span class="cell-text" :title="kind==='merchant'?(item.description || '—'):(item.merchant_name || '—')">{{ kind==='merchant'?(item.description || '—'):(item.merchant_name || '—') }}</span></td><td v-if="kind==='product'"><span class="cell-text" :title="item.category_name || '未分类'">{{ item.category_name || '未分类' }}</span></td><td v-if="kind==='product'"><span class="cell-text" :title="`¥ ${Number(item.price).toFixed(2)}`">¥ {{ Number(item.price).toFixed(2) }}</span></td><td><span class="status" :class="item.status">{{ item.status==='active'?'启用':'停用' }}</span></td><td class="row-actions"><button v-if="kind==='product'" class="link" @click="catalogProduct=item;catalogMode='sku'">规格与库存</button><button class="link" @click="open(item)">编辑</button><button class="link danger" @click="remove(item)">删除</button></td></tr><tr v-if="!items.length"><td :colspan="kind==='product'?8:7" class="empty">{{ loading?'加载中…':error?'加载失败，请重试':'暂无数据' }}</td></tr></tbody></table></div><div class="pagination"><span>{{ queried ? '查询结果' : `每页 20 条 · 第 ${offset/20+1} 页` }}</span><div><button class="secondary" :disabled="queried || offset===0 || loading" @click="page(-1)">上一页</button><button class="secondary" :disabled="!hasNext || loading" @click="page(1)">下一页</button></div></div></div><div v-if="showForm" class="overlay" @click.self="showForm=false"><section class="dialog" role="dialog" aria-modal="true" :aria-label="`${editing?'编辑':'新建'}${title}`"><div class="dialog-head"><h2>{{ editing?'编辑':'新建' }}{{ title }}</h2><button class="close" aria-label="关闭" @click="showForm=false">×</button></div><form @submit.prevent="save"><label>{{ title }}名称<input v-model="form.name" maxlength="120" required placeholder="请输入名称"></label><label v-if="kind==='merchant'">商户类别<select v-model="form.category"><option value="">未分类</option><option v-for="option in categories" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label v-if="kind==='merchant'">商户描述<textarea v-model="form.description" maxlength="500" rows="3" placeholder="请输入商户描述（选填）"></textarea></label><template v-else><label v-if="!editing">所属商户<MerchantSelect :model-value="form.merchant_id" class="merchant-form" :token="token" label="所属商户" @update:model-value="formMerchantChange" /></label><label>商品分类<select v-model="form.category_id" :disabled="!form.merchant_id"><option value="">未分类</option><option v-for="item in formCategories" :key="item.id" :value="String(item.id)" :disabled="item.status==='inactive' && String(item.id)!==form.category_id">{{ item.name }}{{ item.status==='inactive'?'（停用）':'' }}</option></select></label><label>价格（元）<input v-model="form.price" type="number" min="0" step="0.01" required placeholder="请输入价格"></label></template><label>状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="actions"><button type="button" class="secondary" @click="showForm=false">取消</button><button class="primary-btn" :disabled="saving">{{ saving?'保存中…':'保存' }}</button></div></form></section></div><div v-if="catalogMode" class="overlay catalog-overlay" @click.self="closeCatalog"><section class="catalog-dialog" role="dialog" aria-modal="true" :aria-label="catalogMode==='category'?'管理分类':'规格与库存'"><div class="dialog-head"><h2>{{ catalogMode==='category'?'管理商品分类':`规格与库存：${catalogProduct?.name}` }}</h2><button class="close" type="button" aria-label="关闭" @click="closeCatalog">×</button></div><Catalog :key="catalogMode+catalogMerchant+(catalogProduct?.id || '')" :token="token" :mode="catalogMode" :merchant-id="catalogMode==='category'?catalogMerchant:undefined" :product-id="catalogMode==='sku'?String(catalogProduct?.id):undefined" /></section></div></section></template>
<style scoped>
