px}.dialog{background:white;border-radius:9px;width:min(480px,100%);padding:24px;box-shadow:0 20px 60px #15253a30}.dialog-head{margin-bottom:23px}.close{border:0;background:none;font-size:24px;color:#8090a0;cursor:pointer}.dialog label{display:block;font-size:13px;color:#42546a;margin:16px 0}.dialog input,.dialog textarea,.dialog select{display:block;width:100%;margin-top:8px;padding:10px;border:1px solid #dbe3ec;border-radius:5px;font:inherit;color:#263a50;background:white}.dialog textarea{resize:vertical}.error{color:#ba3e3e;font-size:13px}.actions{justify-content:flex-end;margin-top:24px}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid #0073e6;outline-offset:2px}@media(max-width:700px){.management{padding:0 16px 16px}.panel{padding:0}.heading{align-items:flex-start}.pagination{gap:10px}}

.management{flex:1;min-height:0;background:#f0f2f5;padding:20px;gap:14px}.filters{min-height:92px;background:#fff;display:flex;align-items:center;gap:20px;padding:20px;border-radius:6px 6px 0 0}.filters label{display:flex;align-items:center;gap:15px;font-size:14px;color:#192638;white-space:nowrap}.filters input{width:270px;height:40px;border:1px solid #dce3ed;border-radius:6px;padding:0 13px;font:inherit}.filters input::placeholder{color:#b8c2cf}.filter-actions{display:flex;gap:10px;margin-left:auto}.panel{flex:1;min-height:400px;background:#fff;border-radius:0 0 6px 6px;padding:12px 10px 0}.toolbar{min-height:58px;padding:0 0 10px}.toolbar h2{font-size:18px;color:#111c2d}.toolbar-actions{gap:10px}.primary-btn{background:#5267ff;border-color:#5267ff}.primary-btn:hover{background:#4054ed}.secondary{border-color:#dce3ed;color:#334155;background:#fff}.icon-button{height:38px;width:38px;border:1px solid #dce3ed;border-radius:50%;background:white;color:#607087;font-size:22px;cursor:pointer}.table-wrap{border:1px solid #dce4ef;border-radius:5px 5px 0 0;min-height:160px}table{min-width:650px;text-align:center;font-size:14px}th{height:49px;background:#eef3f9;color:#3d4a5b;font-weight:600}th,td{padding:12px 14px;border-bottom:1px solid #dce4ef}th:not(:last-child),td:not(:last-child){border-right:0}td{height:50px;color:#172233}.name{color:#172233;font-weight:400}.status{background:#effcf3;color:#52c878}.status.inactive{background:#f1f3f5;color:#788594}.link{color:#5267ff}.danger{color:#d45f62}.pagination{padding:14px 5px 16px;margin:0;border:0}.pagination button+button{margin-left:8px}.dialog input,.dialog textarea,.dialog select{box-sizing:border-box}
@media(max-width:700px){.management{padding:12px;gap:10px}.filters{padding:14px;flex-wrap:wrap}.filters label{width:100%;flex-wrap:wrap}.filters input{flex:1;min-width:120px}.filter-actions{margin-left:auto}.panel{padding:10px}.toolbar{align-items:flex-start;gap:12px;flex-wrap:wrap}.toolbar-actions{justify-content:flex-end}.table-wrap{min-height:280px}}

